package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OriginEnabledVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property origin enabled of observed source ")
  void test_origin_enabled_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> OriginEnabledVO.tryFrom(null));
    Assertions.assertEquals(true, OriginEnabledVO.from(true).isOriginEnabled());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> OriginEnabledVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", OriginEnabledVO.from(true).toString());
  }
}
